Lemma ro_cells_xpres : forall LB SP X m m' A cs,
  xpres LB SP X m m' -> ro_cells usegs m A cs -> xclient_range LB SP X A (Z.of_nat (cells_size cs)) -> ro_cells usegs m' A cs.
Proof.
  intros LB SP X m m' A cs XP [Hwf HB] HR. split; [exact Hwf|].
  eapply xpres_bytes_at; eauto. rewrite cells_bytes_length by fast_assumption. exact HR.
Qed.
