Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Definition mss_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (R EX SPP FCP lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j0 j48 j8 jc,
      ms' = MS (mkR (Z_to_bv 64 P_MSS_RET1) (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2
                    (Z_to_bv 64 (bv_unsigned sp + -72)) (Z_to_bv 64 R) (Z_to_bv 64 (bv_unsigned sp + -72)) (Z_to_bv 64 0) (Z_to_bv 64 0) a3 a4 a5 a6 a7
                    s2 (Z_to_bv 64 FCP) (Z_to_bv 64 SPP) (Z_to_bv 64 EX) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_SHCOUNT_CTOR_STATE) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -144)
      /\ rw_cells usegs m' (bv_unsigned sp + -144) [CB 8 j0]
      /\ rw_cells usegs m' (bv_unsigned sp + -136) [CB 48 j48]
      /\ rw_cells usegs m' (bv_unsigned sp + -88) [CB 8 j8]
      /\ rw_cells usegs m' (bv_unsigned sp + -80) [C8 (Z_to_bv 64 0)]
      /\ rw_cells usegs m' (bv_unsigned sp + -72) [CB 8 jc]
      /\ rw_cells usegs m' (bv_unsigned sp + -64) [C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.

  Lemma mss_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (R EX SPP FCP lo : Z),
    stk usegs m lo (bv_unsigned sp) -> lo + 144 <= bv_unsigned sp ->
    mem_inv usegs m ->
    evt usegs (mss_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R EX SPP FCP lo m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 R) (Z_to_bv 64 EX) (Z_to_bv 64 SPP) (Z_to_bv 64 FCP) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
