  (* [comment removed for export] *)
  Definition mss_segB2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (R q implb ioc lo : Z) (j7 jm1 : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (mx : word) j4,
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp); (q, q + 32); (q + 80, q + 312); (R, R + 16)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' q (SpcHdrCells (mkSPC VP_SPCI_STATE 1 1 1) j7)
      /\ rw_cells usegs m' (q + 80) [C8 (wz T_ANYEX_PROP_FNS); C8 (wz (implb + 32)); C8 (wz implb)]
      /\ rw_cells usegs m' (q + 104) [CB 80 (zeros 80)]
      /\ rw_cells usegs m' (q + 184) [C8 mx]
      /\ rw_cells usegs m' (q + 192) [CB 60 (zeros 60)]
      /\ rw_cells usegs m' (q + 252) [CB 4 j4; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 mx; C8 mx]
      /\ rw_cells usegs m' R [C8 (wz (q + 32)); C8 (wz q)]
      /\ bv_unsigned mx = u64max.

  Lemma mss_segB2 : forall (rax : word) sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s7 s8 s9 s10 s11 t3 t4 t5 t6 (ra s0 s1 s2 s3 s4 s5 s6 : word)
      (F : bvmap 5 word) fc (m : mem) (R q implb ioc lo : Z) (j7 jm1 jr2 jr j0 : list byte),
    rw_cells usegs m (bv_unsigned sp + -144) [CB 8 j0] ->
    rw_cells usegs m (bv_unsigned sp + -136) [C8 (wz ioc); CB 16 jm1; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz T_ANYEX_PROP_FNS)] ->
    rw_cells usegs m (bv_unsigned sp + -80) [C8 (Z_to_bv 64 0)] ->
    rw_cells usegs m (bv_unsigned sp + -72) [C8 (Z_to_bv 64 q)] ->
    rw_cells usegs m (bv_unsigned sp + -64) [C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells usegs m q (SpcHdrCells (mkSPC VP_SPCI_STATE 1 1 0) j7) ->
    rw_cells usegs m (q + 80) [CB 232 jr2] ->
    rw_cells usegs m R [CB 16 jr] ->
    stk usegs m lo (bv_unsigned sp + -144) -> lo + 176 <= bv_unsigned sp -> hceil <= lo ->
    bv_unsigned sp <= R -> R + 16 <= 2^64 ->
    0 < q -> q mod 16 = 0 -> q + 312 <= lo -> 0 < implb -> implb + 96 <= 2^64 ->
    mem_inv usegs m ->
    evt usegs (mss_segB2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R q implb ioc lo j7 jm1 m)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2
               (Z_to_bv 64 (bv_unsigned sp + -72)) (Z_to_bv 64 R) a0 a1 a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 (q + 24)) (Z_to_bv 64 (q + 32)) (Z_to_bv 64 (implb + 32)) (Z_to_bv 64 implb) (Z_to_bv 64 0) s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_MSS_MID) fc None m (seg_rom usegs)).
