(* [comment removed for export] *)
Lemma ImplBlock_after_mss : forall LB LB' m m' implb SP R (vp u i lk vb : Z) (st : list Z) j7',
  ImplBlock LB m implb (mkIMPL (mkSPC vp u 1 i) lk vb st 0) ->
  xpres LB SP [(R, R + 16); (implb + 12, implb + 16)] m m' ->
  (forall b, In b LB -> In b LB') -> SP <= R -> (forall b, In b LB -> blk_addr b + blk_size b <= hceil) -> hceil <= SP ->
  rw_cells usegs m' implb (SpcHdrCells (mkSPC vp u 2 i) j7') -> 0 <= u < 2^31 ->
  ImplBlock LB' m' implb (mkIMPL (mkSPC vp u 2 i) lk vb st 0).
Proof.
  intros LB LB' m m' implb SP R vp u i lk vb st j7' (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST) XP SUB HR HB CE HDR' U.
  pose proof RB as (R1 & R2 & R3 & R4 & R5). pose proof (HB _ IN) as IB. cbn in IB.
  cbn [im_hdr im_lk im_vb im_states im_vcap] in *. unfold SZ_SPCI_IMPL, O_SPC_STORAGE, O_IMPL_MUTEX, O_IMPL_VEC_BEGIN in *.
  assert (XC : forall A n, implb + 32 <= A -> A + n <= implb + 96 -> xclient_range LB SP [(R, R + 16); (implb + 12, implb + 16)] A n).
  { intros A n HA Hn. split; [right; right; exists (p, implb, 96); split; [exact IN| cbn; lia]|].
    constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor. }
  exists p, j7'. cbn [im_hdr im_lk im_vb im_states im_vcap]. unfold SZ_SPCI_IMPL, O_SPC_STORAGE, O_IMPL_MUTEX, O_IMPL_VEC_BEGIN.
  split; [apply SUB; exact IN|]. split; [exact RB|]. split; [exact HDR'|]. split; [unfold spc_ok in *; cbn in *; lia|]. split; [exact EV|].
  split. { destruct PM as (PC & PL & PA). split; [| split; [exact PL| exact PA]].
           pose proof (rw_cells_bound _ _ _ _ PC) as B0. cbn [cells_size csize Nat.add PMutexCells length zeros repeat] in B0.
           eapply xpres_rw_cells; [exact XP| exact PC|]. apply XC; unfold PMutexCells, zeros; cbn; lia. }
  split. { eapply xpres_rw_cells; [exact XP| exact CV|]. apply XC; cbn; lia. }
  split; [exact LE|].
  destruct ST as [ST|(q & junk & INq & RBq & POS & CS)]; [left; exact ST| exfalso; lia].
Qed.

End HCW.
